package com.concertstage.stage;
import com.concertstage.StageContent;import java.util.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
/** Atomic placement, one-refund group removal and support validation across shared cells. */
public final class StageModules{
 private StageModules(){}public record Piece(BlockPos cell,StageAttachmentBlockEntity.Entry entry){public StageSpec spec(){return StageSpec.get(entry.key());}public double x(){return cell.getX()+entry.x();}public double y(){return cell.getY()+entry.y();}public double z(){return cell.getZ()+entry.z();}}
 private record Snapshot(BlockState state,List<StageAttachmentBlockEntity.Entry> entries){}
 public static InteractionResult fail(UseOnContext c,String key){if(c.getPlayer()!=null&&!c.getLevel().isClientSide)c.getPlayer().displayClientMessage(Component.translatable("message.concertstage."+key),true);return InteractionResult.FAIL;}
 public static List<StageAttachmentBlockEntity.Entry> entries(Level l,BlockPos p){return l.getBlockEntity(p)instanceof StageAttachmentBlockEntity be?be.entries():List.of();}
 /** Pieces held by mount cells: flights, trusses, adapters… and platforms laid by the protractor (support "ground"). */
 public static boolean internal(StageAttachmentBlockEntity.Entry e){StageSpec s=StageSpec.find(e.key());return s!=null&&(s.internal||"ground".equals(e.support())&&StagePlatformAngle.turnable(s)||e.support().startsWith(ON_PIECE));}
 /** 1.2.0 beta 2b: support of a railing set on the edge of a platform laid at an angle: "piece:" + the token of that platform. */
 public static final String ON_PIECE="piece:";
 public static Piece nearest(Level l,BlockPos p,Vec3 hit,String kind){Piece best=null;double dist=.04;for(var e:entries(l,p)){StageSpec s=StageSpec.find(e.key());if(s==null||!internal(e)||kind!=null&&!kind.equals(s.kind))continue;for(double[] b:e.boxes()){double dx=Math.max(p.getX()+b[0]-hit.x,Math.max(0,hit.x-p.getX()-b[3])),dy=Math.max(p.getY()+b[1]-hit.y,Math.max(0,hit.y-p.getY()-b[4])),dz=Math.max(p.getZ()+b[2]-hit.z,Math.max(0,hit.z-p.getZ()-b[5]));double d=dx*dx+dy*dy+dz*dz;if(d<dist){dist=d;best=new Piece(p,e);}}}return best;}
 private static List<BlockPos> cells(double[] b){List<BlockPos> out=new ArrayList<>();int x0=(int)Math.floor(b[0]+1e-7),y0=(int)Math.floor(b[1]+1e-7),z0=(int)Math.floor(b[2]+1e-7),x1=(int)Math.floor(b[3]-1e-7),y1=(int)Math.floor(b[4]-1e-7),z1=(int)Math.floor(b[5]-1e-7);if((long)(x1-x0+1)*(y1-y0+1)*(z1-z0+1)>2048)throw new IllegalArgumentException("Component exceeds cell budget");for(int y=y0;y<=y1;y++)for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++)out.add(new BlockPos(x,y,z));return out;}
 private static List<BlockPos> cells(Piece p){return cells(StagePose.box(p.spec().raw_bounds,p.x(),p.y(),p.z(),p.entry.degrees()));}
 public static boolean place(UseOnContext ctx,StageSpec spec,double x,double y,double z,double angle,String refund,String support,Piece old,Map<BlockPos,BlockState> removeBase){return place(ctx,spec,x,y,z,angle,refund,support,old,removeBase,null);}
 /** {@code host}: token of a piece the new one may touch (a railing clamped on the edge of its platform), else null. */
 public static boolean place(UseOnContext ctx,StageSpec spec,double x,double y,double z,double angle,String refund,String support,Piece old,Map<BlockPos,BlockState> removeBase,String host){angle=((angle%360)+360)%360;Level l=ctx.getLevel();Map<BlockPos,Snapshot> before=new LinkedHashMap<>();Map<BlockPos,List<StageAttachmentBlockEntity.Entry>> after=new LinkedHashMap<>();String token=UUID.randomUUID().toString(),oldToken=old==null?null:old.entry.token();if(old!=null)for(BlockPos p:cells(old))before.put(p,new Snapshot(l.getBlockState(p),entries(l,p)));for(BlockPos p:removeBase.keySet())before.put(p,new Snapshot(l.getBlockState(p),entries(l,p)));
  Map<BlockPos,StageAttachmentBlockEntity.Entry> additions=new LinkedHashMap<>();for(BlockPos p:cells(StagePose.box(spec.raw_bounds,x,y,z,angle))){if(!l.hasChunkAt(p)||!l.isInWorldBounds(p))return false;before.putIfAbsent(p,new Snapshot(l.getBlockState(p),entries(l,p)));String anchor=support;if(support.startsWith("tower@")){String[] v=support.substring(6).split(",");anchor="tower:"+(Integer.parseInt(v[0])-p.getX())+","+(Integer.parseInt(v[1])-p.getY())+","+(Integer.parseInt(v[2])-p.getZ());}additions.put(p,new StageAttachmentBlockEntity.Entry(token,spec.id,x-p.getX(),y-p.getY(),z-p.getZ(),0,new double[]{0,0,0,1,1,1},refund,angle,anchor));}
  List<AABB> collision=new ArrayList<>();for(var row:before.entrySet()){BlockPos p=row.getKey();Snapshot snap=row.getValue();if(ctx.getPlayer()!=null&&!ctx.getPlayer().mayUseItemAt(p,ctx.getClickedFace(),ctx.getItemInHand()))return false;boolean clear=removeBase.containsKey(p);BlockState state=snap.state;if(!clear&&!(state.getBlock()instanceof StageEquipmentBlock)&&!(state.getBlock()instanceof StageMountBlock)&&!state.canBeReplaced())return false;if(!clear&&state.canBeReplaced()&&l.getBlockEntity(p)!=null&&!(l.getBlockEntity(p)instanceof StageAttachmentBlockEntity))return false;List<StageAttachmentBlockEntity.Entry> next=new ArrayList<>();for(var e:snap.entries)if(!Objects.equals(e.token(),oldToken))next.add(e);var add=additions.get(p);
   if(add!=null){List<double[]> boxes=add.boxes();VoxelShape base=clear||state.getBlock()instanceof StageMountBlock?Shapes.empty():state.getBlock()instanceof StageEquipmentBlock b?b.spec.shape(b.part(state),StageSpec.turns(state.getValue(StageEquipmentBlock.FACING)),b.variant(state)):state.getCollisionShape(l,p,CollisionContext.empty());List<double[]> existing=new ArrayList<>();base.forAllBoxes((a,b,c,d,e,f)->existing.add(new double[]{a,b,c,d,e,f}));for(var e:next)if(host==null||!host.equals(e.token()))existing.addAll(e.boxes());for(double[] box:boxes){for(double[] other:existing)if(StageMath.overlaps(box,other,.003))return false;collision.add(new AABB(p.getX()+box[0],p.getY()+box[1],p.getZ()+box[2],p.getX()+box[3],p.getY()+box[4],p.getZ()+box[5]));}next.add(add);}after.put(p,next);}
  if(!collision.isEmpty()){AABB bounds=collision.get(0);for(AABB b:collision)bounds=bounds.minmax(b);for(var entity:l.getEntitiesOfClass(LivingEntity.class,bounds,e->!e.isSpectator()))for(AABB b:collision)if(entity.getBoundingBox().intersects(b))return false;}if(l.isClientSide)return true;
  StageStructure.begin();try{for(var row:after.entrySet()){BlockPos p=row.getKey();Snapshot snap=before.get(p);if(!l.getBlockState(p).equals(snap.state))throw new IllegalStateException("Stage changed during placement");write(l,p,removeBase.containsKey(p)?Blocks.AIR.defaultBlockState():snap.state,row.getValue());}}catch(RuntimeException ex){for(var row:before.entrySet())write(l,row.getKey(),row.getValue().state,row.getValue().entries);return false;}finally{StageStructure.end();}for(BlockPos p:before.keySet()){l.updateNeighborsAt(p,l.getBlockState(p).getBlock());l.scheduleTick(p,l.getBlockState(p).getBlock(),1);}return true;
 }
 private static void write(Level l,BlockPos p,BlockState base,List<StageAttachmentBlockEntity.Entry> value){BlockState desired=base;if(base.getBlock()instanceof StageEquipmentBlock)desired=base.setValue(StageEquipmentBlock.ATTACHED,!value.isEmpty());else if(base.getBlock()instanceof StageMountBlock||base.canBeReplaced())desired=value.isEmpty()?Blocks.AIR.defaultBlockState():StageContent.STAGE_MOUNT.defaultBlockState();if(!l.getBlockState(p).equals(desired)&&!l.setBlock(p,desired,Block.UPDATE_CLIENTS|Block.UPDATE_SUPPRESS_DROPS))throw new IllegalStateException("Mount cell rejected");if(value.isEmpty()){l.removeBlockEntity(p);return;}StageAttachmentBlockEntity be=l.getBlockEntity(p)instanceof StageAttachmentBlockEntity a?a:new StageAttachmentBlockEntity(p,desired);l.setBlockEntity(be);be.replace(value);}
 public static void refund(Level l,BlockPos p,String encoded,Player player){for(var row:StagePose.refunds(encoded).entrySet()){Item item=StageContent.ITEMS.get(row.getKey());if(item==null)continue;ItemStack stack=new ItemStack(item,row.getValue());if(player==null)com.concertstage.block.Drops.give(l,p,stack);else if(!player.getInventory().add(stack))Block.popResource(l,p,stack);}}
 public static void remove(Level l,Piece piece,BlockPos replacing,boolean drops){if(l.isClientSide)return;StageStructure.begin();try{for(BlockPos p:cells(piece)){if(p.equals(replacing))continue;var old=entries(l,p);var next=old.stream().filter(e->!e.token().equals(piece.entry.token())).toList();if(next.size()!=old.size())write(l,p,l.getBlockState(p),next);}}finally{StageStructure.end();}if(piece.spec().kind.equals("adapter")&&piece.entry.support().startsWith("tower:")){try{String[] a=piece.entry.support().substring(6).split(",");BlockPos t=piece.cell.offset(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]));if(l.getBlockState(t).getBlock()instanceof com.concertstage.block.MotorTowerBlock)l.destroyBlock(t,drops);}catch(NumberFormatException ignored){}}if(drops)refund(l,piece.cell,piece.entry.refund(),null);
  // 1.2.0 beta 2b: the railings clamped on this platform go with it (always given back: they are not part of its refund)
  Map<String,Piece> riders=new LinkedHashMap<>();for(BlockPos p:cells(grown(piece,.1)))for(var e:entries(l,p))if(e.support().equals(ON_PIECE+piece.entry.token()))riders.putIfAbsent(e.token(),new Piece(p,e));for(Piece r:riders.values())remove(l,r,null,true);
  for(BlockPos p:cells(piece))l.updateNeighborsAt(p,l.getBlockState(p).getBlock());}
 private static double[] grown(Piece p,double d){double[] b=StagePose.box(p.spec().raw_bounds,p.x(),p.y(),p.z(),p.entry.degrees());for(int i=0;i<3;i++){b[i]-=d;b[i+3]+=d;}return b;}
 /** 1.2.0 beta 2b: the platform a railing is clamped on is still there (a piece with that token near the railing). */
 private static boolean onPieceSupported(Level l,Piece p){String token=p.entry.support().substring(ON_PIECE.length());for(BlockPos c:cells(grown(p,.15))){if(!l.hasChunkAt(c))return true;for(var e:entries(l,c))if(e.token().equals(token))return true;}return false;}
 public static void removedCell(Level l,BlockPos p,boolean drops){Set<String> done=new HashSet<>();for(var e:List.copyOf(entries(l,p)))if(done.add(e.token()))remove(l,new Piece(p,e),p,drops);}
 public static void removedHost(Level l,BlockPos p,boolean drops){Set<String> done=new HashSet<>();for(var e:List.copyOf(entries(l,p)))if(internal(e)&&done.add(e.token()))remove(l,new Piece(p,e),p,drops);}
 public static InteractionResult dismantle(Level l,BlockPos p,Player player,BlockHitResult hit){Piece piece=nearest(l,p,hit.getLocation(),null);if(piece==null)return InteractionResult.PASS;if(piece.spec().kind.equals("flight"))return StageFlights.pop(l,piece,player,hit);if(piece.spec().kind.equals("adapter")){if(!l.isClientSide)remove(l,piece,null,!player.getAbilities().instabuild);return InteractionResult.sidedSuccess(l.isClientSide);}if(!l.isClientSide){remove(l,piece,null,false);if(!player.getAbilities().instabuild)refund(l,p,piece.entry.refund(),player);}return InteractionResult.sidedSuccess(l.isClientSide);}
 private static boolean networkSupported(Level l,Piece start){Deque<Piece> queue=new ArrayDeque<>();Set<String> seen=new HashSet<>();queue.add(start);while(!queue.isEmpty()){Piece p=queue.remove();if(!seen.add(p.entry.token()))continue;if(seen.size()>256)return true;if(StageSurfaces.supported(l,p.spec(),p.x(),p.y(),p.z(),p.entry.degrees()))return true;double[] b=StagePose.box(p.spec().raw_bounds,p.x(),p.y(),p.z(),p.entry.degrees());for(int i=0;i<3;i++){b[i]-=.08;b[i+3]+=.08;}Map<String,Piece> nearby=new LinkedHashMap<>();for(BlockPos c:cells(b)){if(!l.hasChunkAt(c))return true;for(var e:entries(l,c))if(!seen.contains(e.token())&&StageSpec.get(e.key()).kind.equals("truss"))nearby.put(e.token(),new Piece(c,e));}for(Piece q:nearby.values())if(StageRigging.connected(p,q))queue.add(q);}return false;}
 public static void validate(Level l,BlockPos pos){if(l.isClientSide||StageStructure.editing())return;Set<String> seen=new HashSet<>();for(var e:List.copyOf(entries(l,pos))){if(!internal(e)||!seen.add(e.token())||e.support().isEmpty())continue;Piece p=new Piece(pos,e);boolean valid;if(p.spec().kind.equals("truss"))valid=networkSupported(l,p);else if(e.support().startsWith(ON_PIECE))valid=onPieceSupported(l,p);else if(e.support().startsWith("tower:")){try{String[] v=e.support().substring(6).split(",");BlockPos t=pos.offset(Integer.parseInt(v[0]),Integer.parseInt(v[1]),Integer.parseInt(v[2]));valid=!l.hasChunkAt(t)||(l.getBlockState(t).getBlock()instanceof com.concertstage.block.MotorTowerBlock&&StageSurfaces.supported(l,p.spec(),p.x(),p.y(),p.z(),e.degrees()));}catch(RuntimeException ex){valid=false;}}else valid=StageSurfaces.supported(l,p.spec(),p.x(),p.y(),p.z(),e.degrees());if(!valid)remove(l,p,null,true);}}
}
